/// Settings for systematic choices. `Swahili::default()` is what the free functions use.
#[derive(Clone, Copy, Debug, Default)]
pub struct Swahili {
    pub options: Options,
}

impl Swahili {
    /// Keep stress and similar marks in the output (on by default).
    pub fn marks(mut self, on: bool) -> Self {
        self.options.marks = on;
        self
    }

    /// The plural noun.
    pub fn noun_plural_scored(&self, word: &str) -> Scored<String> {
        let cell: Option<u32> = Some(0);
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// The plural noun. The best candidate; the word itself if nothing is known.
    pub fn noun_plural(&self, word: &str) -> String {
        best(self.noun_plural_scored(word), word)
    }

    /// Scored class of a noun.
    pub fn noun_class(&self, word: &str) -> Scored<Class> {
        model().map(|m| m.inherent(0, 0, word).into_iter().filter_map(|(v, p)| Some((Class::ALL.get(v as usize).copied()?, p))).collect()).unwrap_or_default()
    }

    /// Dictionary spelling of a noun (with stress marks where the data has them).
    pub fn noun_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(0, word)).unwrap_or_else(|| word.to_string())
    }

    /// The infinitive verb.
    pub fn verb_infinitive_scored(&self, word: &str) -> Scored<String> {
        let cell: Option<u32> = Some(0);
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(1, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// The infinitive verb. The best candidate; the word itself if nothing is known.
    pub fn verb_infinitive(&self, word: &str) -> String {
        best(self.verb_infinitive_scored(word), word)
    }

    /// The negative infinitive verb.
    pub fn verb_negative_infinitive_scored(&self, word: &str) -> Scored<String> {
        let cell: Option<u32> = Some(1);
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(1, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// The negative infinitive verb. The best candidate; the word itself if nothing is known.
    pub fn verb_negative_infinitive(&self, word: &str) -> String {
        best(self.verb_negative_infinitive_scored(word), word)
    }

    /// A verb form (imperative).
    pub fn verb_imperative_scored(&self, word: &str, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (number,) {
            (Number::Singular,) => Some(2),
            (Number::Plural,) => Some(3),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(1, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A verb form (imperative). The best candidate; the word itself if nothing is known.
    pub fn verb_imperative(&self, word: &str, number: Number) -> String {
        best(self.verb_imperative_scored(word, number), word)
    }

    /// The habitual verb.
    pub fn verb_habitual_scored(&self, word: &str) -> Scored<String> {
        let cell: Option<u32> = Some(4);
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(1, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// The habitual verb. The best candidate; the word itself if nothing is known.
    pub fn verb_habitual(&self, word: &str) -> String {
        best(self.verb_habitual_scored(word), word)
    }

    /// A verb form.
    pub fn verb_scored(&self, word: &str, tense: Tense, person: Person) -> Scored<String> {
        let cell: Option<u32> = match (tense, person,) {
            (Tense::Present, Person::FirstSingular,) => Some(5),
            (Tense::Present, Person::SecondSingular,) => Some(6),
            (Tense::Present, Person::ThirdSingular,) => Some(7),
            (Tense::Present, Person::FirstPlural,) => Some(8),
            (Tense::Present, Person::SecondPlural,) => Some(9),
            (Tense::Present, Person::ThirdPlural,) => Some(10),
            (Tense::NegativePresent, Person::FirstSingular,) => Some(11),
            (Tense::NegativePresent, Person::SecondSingular,) => Some(12),
            (Tense::NegativePresent, Person::ThirdSingular,) => Some(13),
            (Tense::NegativePresent, Person::FirstPlural,) => Some(14),
            (Tense::NegativePresent, Person::SecondPlural,) => Some(15),
            (Tense::NegativePresent, Person::ThirdPlural,) => Some(16),
            (Tense::Subjunctive, Person::FirstSingular,) => Some(17),
            (Tense::Subjunctive, Person::SecondSingular,) => Some(18),
            (Tense::Subjunctive, Person::ThirdSingular,) => Some(19),
            (Tense::Subjunctive, Person::FirstPlural,) => Some(20),
            (Tense::Subjunctive, Person::SecondPlural,) => Some(21),
            (Tense::Subjunctive, Person::ThirdPlural,) => Some(22),
            (Tense::Gnomic, Person::FirstSingular,) => Some(23),
            (Tense::Gnomic, Person::SecondSingular,) => Some(24),
            (Tense::Gnomic, Person::ThirdSingular,) => Some(25),
            (Tense::Gnomic, Person::FirstPlural,) => Some(26),
            (Tense::Gnomic, Person::SecondPlural,) => Some(27),
            (Tense::Gnomic, Person::ThirdPlural,) => Some(28),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(1, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A verb form. The best candidate; the word itself if nothing is known.
    pub fn verb(&self, word: &str, tense: Tense, person: Person) -> String {
        best(self.verb_scored(word, tense, person), word)
    }

    /// Dictionary spelling of a verb (with stress marks where the data has them).
    pub fn verb_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(1, word)).unwrap_or_else(|| word.to_string())
    }

}

